/**
 * Environment bindings + resolved config.
 *
 * `Env` (from `worker-configuration.d.ts`, generated by `wrangler types`) holds
 * the D1/R2 bindings and the public `vars`. Secrets arrive as additional string
 * bindings; we declare them here as an optional `Secrets` interface so the code
 * type-checks whether or not a local `.dev.vars` was present when types were
 * generated. `AppEnv` is what handlers receive.
 *
 * `getConfig` takes nothing on trust: deploy config that would run but do the wrong thing
 * (an unknown provider, a missing origin, a real provider without its credentials, a setting
 * still on the template's example.com placeholders on anything but the fake transport, a
 * minimum lead under the sweep's one-minute tick or over a day, one half of the Access pair
 * without the other, the fake transport on an origin off this machine without the opt-in that
 * says it is on purpose) throws a `ConfigError` naming the variable. A `PROVIDER` left unset is not a mistake but the not-connected state
 * (SPEC §9): the app runs and refuses to send.
 */

import {
  DEFAULT_MIN_LEAD_MS,
  formatLead,
  MIN_LEAD_CEILING_MS,
  MIN_LEAD_FLOOR_MS,
} from "../shared/sends";
import {
  SIMULATION_FAULTS,
  SIMULATION_PROFILES,
  type SimulationFaults,
  type SimulationProfile,
  type SimulationView,
} from "../shared/settings";
import {
  isProviderName,
  isRealProvider,
  PROVIDER_NAMES,
  type ProviderName,
  REQUIRED_VARS,
  type RealProviderName,
} from "./providers/requirements";

export type { ProviderName };

export interface Secrets {
  /**
   * Symmetric secret for signing/verifying the local-dev admin token. Ships in
   * `.dev.vars.example` (so `cp .dev.vars.example .dev.vars` gives a working dev
   * secret) but is NOT committed to `wrangler.jsonc` — a deployed env has no value,
   * which keeps the dev auth path fail-closed. Only honored in a dev-shaped env
   * anyway (see `getConfig`); Cloudflare Access is the gate when deployed.
   */
  DEV_AUTH_SECRET?: string;
  /** Cloudflare Access team domain, e.g. `your-team.cloudflareaccess.com`. */
  ACCESS_TEAM_DOMAIN?: string;
  /** Cloudflare Access application AUD tag. */
  ACCESS_AUD?: string;
  /** Optional comma-separated allowlist of human admin emails (Access logins). */
  ACCESS_ALLOWED_EMAILS?: string;
  /** SES / SigV4. */
  AWS_ACCESS_KEY_ID?: string;
  AWS_SECRET_ACCESS_KEY?: string;
  SES_CONFIGURATION_SET?: string;
  /** The SES account's maximum send rate, in messages a second (optional). */
  SES_MAX_SEND_RATE?: string;
  SNS_TOPIC_ARN?: string;
  /**
   * What stands in for the provider in local dev (SPEC §10): the send simulation, naming the
   * provider it models, `ses` or `generic` (`1`), optionally with `:none` for no
   * injected failures; `not-connected` to run as a deployment with no provider (SPEC §9);
   * `off` or unset for the plain, instant fake. Honored only in a dev-shaped env, so never
   * in a deployed one. `.dev.vars.example` ships it on.
   */
  SIMULATE_SENDS?: string;
}

/**
 * Optional public vars: not secrets, but left out of `wrangler.jsonc` by default, so
 * they are declared here rather than generated into `Env`.
 */
export interface OptionalVars {
  /**
   * The origin the public archive's links use, when it is surfaced on a website apex
   * (SPEC §11). Unset means `APP_ORIGIN`.
   */
  ARCHIVE_ORIGIN?: string;
  /** Base URL images are served from, when a media custom domain is set. Unset means
   *  `${APP_ORIGIN}/media`. */
  MEDIA_PUBLIC_BASE?: string;
  /**
   * Subrequests (D1 statements plus outbound requests) one invocation of the send path
   * may make. Unset means the Workers Free plan's 50; raise it on Workers Paid.
   */
  SUBREQUEST_BUDGET?: string;
  /**
   * The minimum lead in seconds (SPEC §6): how long every send stays visible and cancelable
   * before it fires, at the least. Unset means five minutes; below sixty or above a day (86400) is refused.
   */
  MIN_LEAD_SECONDS?: string;
  /**
   * The `From:` of the notifications that email the publisher through Cloudflare (SPEC §8): an
   * address on a domain onboarded to Cloudflare's email sending. Unset means
   * `kestrel@` the app's own hostname.
   */
  NOTIFY_FROM?: string;
  /**
   * The ID `kestrel dev` makes up for one run of the local dev server and records beside its
   * port, so the CLI's seed and reset can tell this directory's server from another's before
   * wiping a database. Set by `kestrel dev` alone; honored only in local dev (see `devRunId`).
   */
  DEV_RUN_ID?: string;
  /**
   * `true` lets `PROVIDER: "fake"` run on an origin off this machine, for a hosted demo that
   * mails no one on purpose (SPEC §9). Unset, the fake is refused anywhere but a loopback
   * origin, since a deployment on it records every send as delivered and mails no one. Has no
   * effect on any other provider.
   */
  ALLOW_FAKE_PROVIDER?: string;
}

/**
 * Optional bindings, declared by hand because the development config never carries them,
 * so `wrangler types` does not generate them into `Env`.
 */
export interface OptionalBindings {
  /**
   * Cloudflare's `send_email` binding, the channel that tells the publisher when a send
   * goes out or runs into a problem (SPEC §8). Deploy-time infrastructure (SPEC §9): its presence
   * picks the channel, and it is never declared for development, where notifications go to the
   * in-memory fake.
   */
  NOTIFY?: SendEmail;
}

export type AppEnv = Env & Secrets & OptionalVars & OptionalBindings;

/**
 * How notifications reach the publisher (SPEC §8): Cloudflare's own email when the `NOTIFY`
 * binding is declared, the newsletter's provider otherwise, and the in-memory fake in a
 * dev-shaped env whatever is bound, so development can never reach a real inbox.
 */
export type NotifyChannel = "fake" | "cloudflare" | "provider";

export interface Config {
  /** The transport, or `none` when no provider is connected (SPEC §9): the app then runs
   *  and refuses everything that would send. Local dev's `SIMULATE_SENDS=not-connected`
   *  sets it too, so the preview of that state runs the same code as the real one. */
  provider: ProviderName;
  /** Origin the app is served from (API + reader routes). */
  appOrigin: string;
  /** Origin the public archive lives on. Defaults to `appOrigin` (self-contained);
   *  set to the apex only as the opt-in Cloudflare enhancement (SPEC §11). */
  archiveOrigin: string;
  /** Base path for archive pages, e.g. `/archive`. Drives both the emitted
   *  archive URL and the route that serves it (SPEC §11); defaults to `/archive`. */
  archiveBasePath: string;
  /** Public base URL for R2-served images. Defaults to the Worker's own `/media`
   *  route; a `media.` custom domain is the optional upgrade (SPEC §11). */
  mediaPublicBase: string;
  /** Sending identity domain, e.g. `send.example.com`. */
  sendingDomain: string;
  /** `From:` header value. */
  fromAddress: string;
  /** AWS region for SES. */
  awsRegion: string;
  /**
   * The SES account's maximum send rate, in messages a second, which sizes the SES adapter's
   * batches, sent one a second: going over it is a throttle, which halts the send for at
   * least a minute. Defaults to 14, a common starting rate that AWS does not promise any
   * account; the SES sandbox allows 1, and the account dashboard shows the account's own.
   */
  sesMaxSendRate: number;
  /** Cloudflare Access: both set, enabling JWT validation, or neither (one alone is refused). */
  accessTeamDomain?: string;
  accessAud?: string;
  /** Optional allowlist of human admin emails; empty/unset allows any valid Access login. */
  accessAllowedEmails?: string[];
  /**
   * True only in a dev-shaped env with the dev credential live (fake transport, no
   * Access, a loopback `APP_ORIGIN`, dev secret present): the single case where
   * `/dashboard` is reachable without an Access wall, because the editor auto-mints a
   * dev token on load. It decides whether the `/api/dev/*` routes exist at all (`app.ts`
   * registers them only here), and gates the dev-only "Open dashboard" link the public
   * reader surface injects for a local developer (SPEC §5, §11). Structurally false in
   * any deployed env, so there the dev routes are absent and the reader surface never
   * links toward the Access gate. The admin/public gate in `app.ts` is identical in every
   * environment.
   */
  devMode: boolean;
  /**
   * Fake transport, no Access, and a loopback `APP_ORIGIN`: the shape in which the dev
   * credential may be honored, whether or not its secret is present. Outside it, with no
   * Access configured, no admin request can authenticate, so the 401 says why (SPEC §11).
   */
  devShaped: boolean;
  /**
   * Local-dev admin-token secret, resolved ONLY in a dev-shaped env (see `devMode`).
   * Undefined in any deployed env, which disables the dev credential path entirely:
   * Access is then the only door.
   */
  devAuthSecret?: string;
  /**
   * This run's `DEV_RUN_ID`, which `/api/dev/token` reports. Resolved only when `devMode`
   * holds, like the routes that report it, so a deployed env never carries one.
   */
  devRunId?: string;
  /**
   * The local send simulation that stands in for a provider on list sends (SPEC §10), or
   * null for the plain fake and the not-connected preview. Only ever set in a dev-shaped
   * env, from `SIMULATE_SENDS`, so it is structurally null once deployed (no deployed env
   * is dev-shaped) and can never pace or fabricate events against a real inbox.
   */
  simulation: SimulationView | null;
  /**
   * True when local dev runs as a deployment with no provider (`SIMULATE_SENDS=not-connected`,
   * SPEC §10): `provider` is then `none`, and the way out is a restart, not a deploy. Like
   * `simulation`, only ever true in a dev-shaped env, so never once deployed.
   */
  notConnectedPreview: boolean;
  /**
   * How many subrequests (D1 statements plus outbound requests) one invocation of the
   * send path may make: the send loop stops starting batches before it would pass this,
   * and the next sweep tick continues. D1 statements are held to Cloudflare's own cap of
   * 1,000 besides (`budget.ts`). Defaults to the Workers Free plan's 50, so a new
   * deployment is correct on any plan; Workers Paid allows 10,000.
   */
  subrequestBudget: number;
  /**
   * The minimum lead (SPEC §6, I6): the least time between a request to send and the send
   * firing, which every schedule, send now, reschedule, and re-make enforces. Deploy config,
   * never a preference behind the API: the API is also Claude's door, and a review window
   * Claude could shorten through it would be no guard against Claude.
   */
  minLeadMs: number;
  /** The channel notifications to the publisher go through (see `NotifyChannel`). */
  notifyChannel: NotifyChannel;
  /** The `From:` a notification carries: `NOTIFY_FROM` on the Cloudflare channel, else the
   *  newsletter's own `From:`, the only sender its provider will take. */
  notifyFrom: string;
}

/** The SES send rate assumed when `SES_MAX_SEND_RATE` is unset, in messages a second: a
 *  common starting rate for a production account, though AWS sets each account's own. */
export const DEFAULT_SES_MAX_SEND_RATE = 14;
/** The Workers Free plan's per-invocation subrequest limit, the default budget. */
export const DEFAULT_SUBREQUEST_BUDGET = 50;

/**
 * Whether the deployment runs on the Workers Free plan's limits, judged from
 * `SUBREQUEST_BUDGET` left at Free's default: the one setting that tells Free from Paid, for
 * the import limit, the export's page, and the advice to move to Workers Paid (SPEC §7, §8).
 */
export function onFreePlanLimits(config: Pick<Config, "subrequestBudget">): boolean {
  return config.subrequestBudget <= DEFAULT_SUBREQUEST_BUDGET;
}
/** The least a sweep tick needs to find a send and deliver one batch of it, beside what it
 *  holds back for its own checks and one notification. A lower `SUBREQUEST_BUDGET` would
 *  start nothing and stall every send silently, so it is raised to this. */
export const MIN_SUBREQUEST_BUDGET = 30;

const orUndefined = (v: string | undefined): string | undefined =>
  v && v.length > 0 ? v : undefined;

/** Leading-slash, no-trailing-slash form; defaults to `/archive`. Drives both
 *  the archive URL and the route registered to serve it, so the two can't drift. */
function normalizeBasePath(v: string | undefined): string {
  const raw = (orUndefined(v) ?? "/archive").trim();
  const withLead = raw.startsWith("/") ? raw : `/${raw}`;
  return withLead.length > 1 && withLead.endsWith("/") ? withLead.slice(0, -1) : withLead;
}

/**
 * Deploy config the app cannot run on as given. Names the variable, so the admin surface's
 * refusal and the line it logs both say what to fix (a reader is told only that the page is
 * unavailable). Never carries a secret's value: secrets are only ever checked for presence.
 */
export class ConfigError extends Error {
  constructor(
    readonly variable: string,
    detail: string,
  ) {
    super(`${variable} ${detail}`);
    this.name = "ConfigError";
  }
}

/** Resolve the typed `Config` from raw bindings. Pure; no I/O. Throws `ConfigError` on
 *  deploy config that would run wrong rather than fail (see the module header).
 *  Self-contained by default (SPEC §11): the archive origin and media base fall
 *  back to the app's own origin, so a deployment that sets only `APP_ORIGIN`
 *  serves archives and images on its own hostname with no further assumptions. */
export function getConfig(env: AppEnv): Config {
  const provider = readProvider(env.PROVIDER);
  const appOrigin = readOrigin("APP_ORIGIN", env.APP_ORIGIN);
  if (!appOrigin) {
    throw new ConfigError("APP_ORIGIN", "is not set; it is the origin the app is served from");
  }
  const archiveOrigin = readOrigin("ARCHIVE_ORIGIN", env.ARCHIVE_ORIGIN) ?? appOrigin;
  const mediaPublicBase =
    readBaseUrl("MEDIA_PUBLIC_BASE", env.MEDIA_PUBLIC_BASE) ?? `${appOrigin}/media`;
  if (isRealProvider(provider)) {
    requireRealProviderConfig(provider, env);
  }
  if (provider === "fake") {
    refuseFakeOffThisMachine(appOrigin, env.ALLOW_FAKE_PROVIDER);
  } else {
    refusePlaceholders(provider, env, { appOrigin, archiveOrigin, mediaPublicBase });
  }
  const { accessTeamDomain, accessAud } = readAccess(env);
  // Belt-and-suspenders: only honor the dev credential when the env is unambiguously
  // dev-shaped: fake transport, no Access configured, AND an origin on this machine.
  // Combined with the secret never being committed (it lives in the gitignored
  // `.dev.vars`, not in `wrangler.jsonc` vars), a deployed Worker has no secret and this
  // stays undefined, so the dev auth path is off and Access is the only door. The loopback
  // origin also catches a fake, Access-less deploy given its real hostname with `.dev.vars`
  // uploaded as secrets. Config alone cannot tell the development config deployed wholly
  // unchanged (its origin still names localhost) from local dev; that deploy is
  // misconfigured anyway, since every link it emits points at localhost. A real provider
  // or Access, either of which every real deployment has, turns this path off regardless.
  // This one predicate is also what `devMode` (and so the dev routes) keys on, so "this is
  // local dev" has a single source.
  const devShaped = provider === "fake" && !accessTeamDomain && isLoopbackOrigin(appOrigin);
  const devAuthSecret = devShaped ? orUndefined(env.DEV_AUTH_SECRET) : undefined;
  const devMode = devAuthSecret !== undefined;
  // Only ever read in a dev-shaped env; a deployed env is never dev-shaped, so neither the
  // simulation nor the not-connected preview can engage there whatever the var says.
  const local = devShaped ? readSimulateSends(env.SIMULATE_SENDS) : null;
  const notConnectedPreview = local === "not-connected";
  // The preview runs as a deployment with no provider and no `NOTIFY` binding does: the
  // provider channel, over the not-connected adapter, which carries nothing.
  const notifyChannel: NotifyChannel = notConnectedPreview
    ? "provider"
    : devShaped
      ? "fake"
      : env.NOTIFY
        ? "cloudflare"
        : "provider";
  return {
    // The preview changes the provider alone, after `devShaped` was decided on the fake, so
    // local sign-in stays on while every send path takes the real not-connected route.
    provider: notConnectedPreview ? "none" : provider,
    appOrigin,
    archiveOrigin,
    archiveBasePath: normalizeBasePath(env.ARCHIVE_BASE_PATH),
    mediaPublicBase,
    sendingDomain: env.SENDING_DOMAIN,
    fromAddress: env.FROM_ADDRESS,
    awsRegion: env.AWS_REGION,
    sesMaxSendRate:
      readPositiveInt("SES_MAX_SEND_RATE", env.SES_MAX_SEND_RATE) ?? DEFAULT_SES_MAX_SEND_RATE,
    accessTeamDomain,
    accessAud,
    accessAllowedEmails: parseEmailList(env.ACCESS_ALLOWED_EMAILS),
    // Show the dev-only dashboard link, and register the dev routes, exactly when the
    // dev credential path is live (dev-shaped AND the secret resolved). Never true in a
    // deployed env, so the reader surface stays clean of any admin link there.
    devMode,
    devShaped,
    devAuthSecret,
    devRunId: devMode ? orUndefined(env.DEV_RUN_ID) : undefined,
    simulation: local === "not-connected" ? null : local,
    notConnectedPreview,
    subrequestBudget: Math.max(
      MIN_SUBREQUEST_BUDGET,
      readPositiveInt("SUBREQUEST_BUDGET", env.SUBREQUEST_BUDGET) ?? DEFAULT_SUBREQUEST_BUDGET,
    ),
    minLeadMs: readMinLead(env.MIN_LEAD_SECONDS),
    notifyChannel,
    notifyFrom:
      notifyChannel === "cloudflare"
        ? (orUndefined(env.NOTIFY_FROM) ?? `Kestrel <kestrel@${new URL(appOrigin).hostname}>`)
        : env.FROM_ADDRESS,
  };
}

/**
 * The Access pair, both or neither. One without the other can verify no sign-in, and it
 * also takes the env out of dev shape, so it would turn every door off at once: every admin
 * request a 401 that says nothing of why. Refused instead, naming the half that is missing.
 * The team domain comes back as a bare host (`readTeamDomain`).
 */
function readAccess(env: AppEnv): { accessTeamDomain?: string; accessAud?: string } {
  const accessTeamDomain = orUndefined(env.ACCESS_TEAM_DOMAIN?.trim());
  const accessAud = orUndefined(env.ACCESS_AUD?.trim());
  if (accessTeamDomain && !accessAud) {
    throw new ConfigError(
      "ACCESS_AUD",
      "is not set, but ACCESS_TEAM_DOMAIN is; Access needs both to verify a sign-in",
    );
  }
  if (accessAud && !accessTeamDomain) {
    throw new ConfigError(
      "ACCESS_TEAM_DOMAIN",
      "is not set, but ACCESS_AUD is; Access needs both to verify a sign-in",
    );
  }
  return {
    accessTeamDomain: accessTeamDomain && readTeamDomain(accessTeamDomain),
    accessAud,
  };
}

/** A hostname: dot-separated labels of letters, digits, and inner hyphens, at least two. */
const HOSTNAME = /^(?!-)[a-z0-9-]{1,63}(?<!-)(\.(?!-)[a-z0-9-]{1,63}(?<!-))+$/;

/**
 * The team domain as the bare host the issuer is built on (`https://<host>`). Pasting it
 * with its scheme or a trailing slash is the natural mistake, and kept as typed it would
 * fail every sign-in as a 401 that names nothing, so those are dropped and the case folded.
 * Anything still not a hostname (a path, a port, a stray character) is refused. The value
 * is a secret, so the refusal never repeats it.
 */
function readTeamDomain(raw: string): string {
  const host = raw
    .replace(/^https?:\/\//i, "")
    .replace(/\/+$/, "")
    .toLowerCase();
  if (!HOSTNAME.test(host)) {
    throw new ConfigError(
      "ACCESS_TEAM_DOMAIN",
      "must be your team's hostname, like yourteam.cloudflareaccess.com",
    );
  }
  return host;
}

/** `PROVIDER` as one of the known names, exactly as spelled. Unset means `none`, not
 *  connected (SPEC §9), on every host alike: the fake runs only where it is named, since a
 *  deployment that fell back to it would record every recipient accepted and mail no one.
 *  Anything else unknown is an error. */
function readProvider(v: string | undefined): ProviderName {
  const raw = orUndefined(v);
  if (raw === undefined) {
    return "none";
  }
  if (raw === "resend") {
    // An instance made before Resend was removed: say what to do, not only what's allowed.
    throw new ConfigError(
      "PROVIDER",
      'is "resend", which this release no longer supports. Set it to "ses": Connect Amazon SES in the setup guide walks through it, and its last section says how to switch an instance that already sends',
    );
  }
  if (!isProviderName(raw)) {
    throw new ConfigError("PROVIDER", `must be one of ${PROVIDER_NAMES.join(", ")}, not "${raw}"`);
  }
  return raw;
}

/**
 * The fake runs only on this machine unless a deployment says otherwise (SPEC §9). It records
 * every recipient accepted and mails no one, so on a real hostname, copied into the
 * production config by mistake, it would open signups whose confirmations go nowhere and lose
 * every post it sends (I4). The same loopback test as the dev-shaped predicate, so "this
 * machine" means one thing. A hosted demo that runs the fake on purpose opts in by name.
 */
function refuseFakeOffThisMachine(appOrigin: string, allow: string | undefined): void {
  const raw = orUndefined(allow?.trim());
  if (raw !== undefined && raw !== "true") {
    throw new ConfigError("ALLOW_FAKE_PROVIDER", `must be "true" or unset, not "${raw}"`);
  }
  if (raw === undefined && !isLoopbackOrigin(appOrigin)) {
    throw new ConfigError(
      "PROVIDER",
      `is "fake", which delivers nothing, and runs only on a local APP_ORIGIN (localhost or 127.0.0.1), not ${appOrigin}: set your email provider, or leave PROVIDER empty until you connect one`,
    );
  }
}

/** What a real transport needs before it may run: its credentials and a `From:` address. */
function requireRealProviderConfig(provider: RealProviderName, env: AppEnv): void {
  for (const name of [...REQUIRED_VARS[provider], "FROM_ADDRESS"] as const) {
    const value = env[name];
    if (typeof value !== "string" || value.trim() === "") {
      throw new ConfigError(name, `is not set; PROVIDER "${provider}" needs it`);
    }
  }
  if (!addressDomain(env.FROM_ADDRESS)) {
    throw new ConfigError(
      "FROM_ADDRESS",
      `must be an email address, optionally with a name, not "${env.FROM_ADDRESS}"`,
    );
  }
}

/**
 * No setting may stay on the template's example.com placeholder anywhere but the fake
 * transport (SPEC §9). Not connected too: every link the app builds would name the
 * placeholder, and archive URLs, once mailed, are permanent (I3), so the mistake is caught
 * at the deploy that carried it rather than at the provider step after it. A derived origin
 * is checked under the setting it came from, which is refused first.
 */
function refusePlaceholders(
  provider: Exclude<ProviderName, "fake">,
  env: AppEnv,
  origins: { appOrigin: string; archiveOrigin: string; mediaPublicBase: string },
): void {
  const hosts: [string, string][] = [
    ["APP_ORIGIN", new URL(origins.appOrigin).hostname],
    ["ARCHIVE_ORIGIN", new URL(origins.archiveOrigin).hostname],
    ["MEDIA_PUBLIC_BASE", new URL(origins.mediaPublicBase).hostname],
  ];
  if (orUndefined(env.SENDING_DOMAIN?.trim())) {
    hosts.push(["SENDING_DOMAIN", env.SENDING_DOMAIN.trim()]);
  }
  // Not connected, a From the app cannot parse is left for the provider step to refuse;
  // only its domain, when it has one, is checked here.
  const from = orUndefined(env.FROM_ADDRESS?.trim());
  const fromDomain = from && addressDomain(from);
  if (fromDomain) {
    hosts.push(["FROM_ADDRESS", fromDomain]);
  }
  const why =
    provider === "none"
      ? "replace it with your own domain"
      : `PROVIDER "${provider}" sends real email`;
  for (const [name, host] of hosts) {
    if (isPlaceholderHost(host)) {
      throw new ConfigError(name, `is still on the template's example.com placeholder; ${why}`);
    }
  }
}

/** The domain of a `From:` value, `Name <local@domain>` or a bare address, or `undefined`
 *  when it holds no address. */
function addressDomain(from: string): string | undefined {
  // The address is the last `<…>`, so a display name that itself contains angle brackets
  // is not mistaken for it.
  const address = /<([^<>]*)>\s*$/.exec(from)?.[1] ?? from;
  const at = address.lastIndexOf("@");
  if (at < 1 || at === address.length - 1) {
    return undefined;
  }
  return address.slice(at + 1).trim();
}

function isPlaceholderHost(host: string): boolean {
  const h = host.toLowerCase().replace(/\.$/, "");
  return h === "example.com" || h.endsWith(".example.com");
}

function isLoopbackOrigin(origin: string): boolean {
  const host = new URL(origin).hostname;
  return host === "localhost" || host === "127.0.0.1";
}

/** A URL value as it may appear in an error, which is a public 500 and a log line: any
 *  `user:password@` it carries is hidden, so a credential never leaves in a message. */
function redactUserinfo(raw: string): string {
  return raw.replace(/\/\/[^/?#]*@/, "//…@");
}

/** An http(s) URL with no credentials, query, or fragment. */
function parseHttpUrl(name: string, raw: string): URL {
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    throw new ConfigError(name, `must be an http(s) URL, not "${redactUserinfo(raw)}"`);
  }
  if (
    (url.protocol !== "http:" && url.protocol !== "https:") ||
    url.username ||
    url.password ||
    url.search ||
    url.hash
  ) {
    throw new ConfigError(name, `must be a plain http(s) URL, not "${redactUserinfo(raw)}"`);
  }
  return url;
}

/** An origin var (scheme, host, port; a trailing slash is dropped), or undefined when
 *  unset. A path is refused rather than ignored, since it would never be honored. */
function readOrigin(name: string, v: string | undefined): string | undefined {
  const raw = orUndefined(v?.trim());
  if (raw === undefined) {
    return undefined;
  }
  const url = parseHttpUrl(name, raw);
  if (!/^\/*$/.test(url.pathname)) {
    throw new ConfigError(
      name,
      `must be an origin (scheme and host, no path), not "${redactUserinfo(raw)}"`,
    );
  }
  return url.origin;
}

/** A base URL var (an origin, optionally with a path) with trailing slashes dropped, so
 *  the URLs built on it never double a slash; undefined when unset. */
function readBaseUrl(name: string, v: string | undefined): string | undefined {
  const raw = orUndefined(v?.trim());
  if (raw === undefined) {
    return undefined;
  }
  const url = parseHttpUrl(name, raw);
  return `${url.origin}${url.pathname.replace(/\/+$/, "")}`;
}

/** A whole number above zero, or undefined when unset or blank. Anything else is refused
 *  rather than quietly defaulted, so a typo can't pass for the default. */
function readPositiveInt(name: string, v: string | undefined): number | undefined {
  const raw = orUndefined(v?.trim());
  if (raw === undefined) {
    return undefined;
  }
  const n = Number(raw);
  if (!Number.isInteger(n) || n <= 0) {
    throw new ConfigError(name, `must be a whole number above zero, not "${raw}"`);
  }
  return n;
}

/**
 * `MIN_LEAD_SECONDS` in milliseconds, or the default when unset. One floor in every
 * environment, local dev included: the sweep runs once a minute, so under that the tick,
 * not the lead, would decide when a send fires. The ceiling, one day, catches a value in
 * milliseconds. A value outside the two is refused rather than clamped, so a deployment
 * never runs on a lead other than the one it names.
 */
function readMinLead(v: string | undefined): number {
  const seconds = readPositiveInt("MIN_LEAD_SECONDS", v);
  if (seconds === undefined) {
    return DEFAULT_MIN_LEAD_MS;
  }
  if (seconds * 1000 < MIN_LEAD_FLOOR_MS) {
    throw new ConfigError(
      "MIN_LEAD_SECONDS",
      `must be at least ${MIN_LEAD_FLOOR_MS / 1000}, not "${v?.trim()}": the send sweep runs once a minute, so under ${formatLead(MIN_LEAD_FLOOR_MS)} the tick, not the lead, would decide when a send fires`,
    );
  }
  if (seconds * 1000 > MIN_LEAD_CEILING_MS) {
    throw new ConfigError(
      "MIN_LEAD_SECONDS",
      `must be at most ${MIN_LEAD_CEILING_MS / 1000} (one day), not "${v?.trim()}": it is in seconds, and it is the least wait before every send, not a limit on how far out one can be scheduled`,
    );
  }
  return seconds * 1000;
}

/** The spellings that turn the simulation off, and those that pick the generic profile. */
const SIMULATION_OFF = new Set(["", "0", "off", "false", "no"]);
const SIMULATION_GENERIC = new Set(["1", "on", "true", "yes"]);

/**
 * `SIMULATE_SENDS` as a profile and fault level, `not-connected`, or null for the plain
 * fake: `off` (or unset), `not-connected`, or a profile (`generic`, or `1`, `ses`)
 * and optionally `:realistic` (the default) or `:none`. Anything else is refused rather than
 * read as off, so a typo can't quietly turn the simulation off or pick the wrong provider.
 */
function readSimulateSends(v: string | undefined): SimulationView | "not-connected" | null {
  const raw = (v ?? "").trim().toLowerCase();
  if (SIMULATION_OFF.has(raw)) {
    return null;
  }
  if (raw === "not-connected") {
    return "not-connected";
  }
  const [name = "", faults = "realistic", ...rest] = raw.split(":");
  const profile = SIMULATION_GENERIC.has(name) ? "generic" : name;
  if (
    rest.length > 0 ||
    !(SIMULATION_PROFILES as readonly string[]).includes(profile) ||
    !(SIMULATION_FAULTS as readonly string[]).includes(faults)
  ) {
    throw new ConfigError(
      "SIMULATE_SENDS",
      `must be off, one of ${SIMULATION_PROFILES.join(", ")} (or 1) optionally followed by :${SIMULATION_FAULTS.join(" or :")}, or not-connected, not "${v?.trim()}"`,
    );
  }
  return { profile: profile as SimulationProfile, faults: faults as SimulationFaults };
}

function parseEmailList(v: string | undefined): string[] | undefined {
  if (!v) {
    return undefined;
  }
  const list = v
    .split(",")
    .map((e) => e.trim().toLowerCase())
    .filter(Boolean);
  return list.length ? list : undefined;
}
